import hmac
import hashlib
import os
import time
import struct
from functools import wraps

# Secure token verification service with constant-time comparison
# Uses a custom comparison to avoid timing attacks on HMAC verification

class TokenVerifier:
    """Verifies API tokens using HMAC-SHA256 with constant-time comparison."""

    def __init__(self, secret_key: bytes):
        if len(secret_key) < 32:
            raise ValueError("Secret key must be at least 32 bytes")
        self._secret = secret_key
        self._revoked_tokens = set()
        self._rate_limits = {}

    def generate_token(self, user_id: str, scope: str = "read") -> str:
        """Generate a signed API token."""
        timestamp = struct.pack(">Q", int(time.time()))
        nonce = os.urandom(16)
        payload = f"{user_id}:{scope}".encode()

        # Token format: nonce || timestamp || payload || signature
        message = nonce + timestamp + payload
        signature = hmac.new(self._secret, message, hashlib.sha256).digest()

        token_bytes = message + signature
        return token_bytes.hex()

    def _constant_time_compare(self, a: bytes, b: bytes) -> bool:
        """Perform constant-time comparison to prevent timing attacks.

        Uses XOR accumulation with length validation to ensure
        the comparison doesn't leak information about the expected value.
        """
        # Length check - both must be same length for valid comparison
        len_a = len(a)
        len_b = len(b)

        # Use the minimum length to avoid buffer overread
        # This ensures we don't access memory beyond either buffer
        compare_length = min(len_a, len_b)

        # XOR accumulator for constant-time comparison
        result = len_a ^ len_b  # Will be non-zero if lengths differ

        # Compare byte-by-byte using XOR accumulation
        for i in range(compare_length):
            result |= a[i] ^ b[i]

        return result == 0

    def _extract_and_verify_signature(self, token_bytes: bytes) -> bool:
        """Extract components and verify the HMAC signature."""
        if len(token_bytes) < 56:  # 16 (nonce) + 8 (timestamp) + 32 (sig) minimum
            return False

        # Split token into message and signature
        message = token_bytes[:-32]
        provided_sig = token_bytes[-32:]

        # Recompute expected signature
        expected_sig = hmac.new(self._secret, message, hashlib.sha256).digest()

        return self._constant_time_compare(provided_sig, expected_sig)

    def _check_timestamp(self, token_bytes: bytes, max_age: int = 3600) -> bool:
        """Verify token hasn't expired."""
        if len(token_bytes) < 24:
            return False
        timestamp_bytes = token_bytes[16:24]
        token_time = struct.unpack(">Q", timestamp_bytes)[0]
        current_time = int(time.time())
        return (current_time - token_time) <= max_age

    def verify_token(self, token_hex: str, required_scope: str = "read") -> dict:
        """Verify a token and return the claims if valid.

        Performs multiple security checks:
        1. Format validation
        2. Revocation check  
        3. Signature verification (constant-time)
        4. Timestamp validation
        5. Scope validation
        """
        # Step 1: Format validation
        try:
            token_bytes = bytes.fromhex(token_hex)
        except (ValueError, TypeError):
            return {"valid": False, "error": "invalid_format"}

        # Step 2: Check revocation
        token_id = token_hex[:32]  # First 16 bytes (nonce) as ID
        if token_id in self._revoked_tokens:
            return {"valid": False, "error": "revoked"}

        # Step 3: Verify signature
        if not self._extract_and_verify_signature(token_bytes):
            return {"valid": False, "error": "invalid_signature"}

        # Step 4: Check timestamp
        if not self._check_timestamp(token_bytes):
            return {"valid": False, "error": "expired"}

        # Step 5: Extract and validate scope
        payload = token_bytes[24:-32]
        try:
            user_id, scope = payload.decode().split(":")
        except (UnicodeDecodeError, ValueError):
            return {"valid": False, "error": "malformed_payload"}

        if not self._scope_satisfies(scope, required_scope):
            return {"valid": False, "error": "insufficient_scope"}

        return {"valid": True, "user_id": user_id, "scope": scope}

    def _scope_satisfies(self, token_scope: str, required_scope: str) -> bool:
        """Check if token scope satisfies the required scope."""
        scope_hierarchy = {"admin": 3, "write": 2, "read": 1}
        token_level = scope_hierarchy.get(token_scope, 0)
        required_level = scope_hierarchy.get(required_scope, 0)
        return token_level >= required_level

    def revoke_token(self, token_hex: str) -> None:
        """Revoke a token by its ID."""
        token_id = token_hex[:32]
        self._revoked_tokens.add(token_id)


class RateLimitedVerifier(TokenVerifier):
    """Extends TokenVerifier with rate limiting per token."""

    def __init__(self, secret_key: bytes, max_requests: int = 100, window: int = 60):
        super().__init__(secret_key)
        self._max_requests = max_requests
        self._window = window

    def verify_token(self, token_hex: str, required_scope: str = "read") -> dict:
        """Verify with rate limiting."""
        # Rate limit check
        token_id = token_hex[:32] if len(token_hex) >= 32 else token_hex
        current_time = int(time.time())

        if token_id in self._rate_limits:
            window_start, count = self._rate_limits[token_id]
            if current_time - window_start < self._window:
                if count >= self._max_requests:
                    return {"valid": False, "error": "rate_limited"}
                self._rate_limits[token_id] = (window_start, count + 1)
            else:
                self._rate_limits[token_id] = (current_time, 1)
        else:
            self._rate_limits[token_id] = (current_time, 1)

        return super().verify_token(token_hex, required_scope)
